"""Migration of Meridian CRM 4.2 order validation rules."""

from decimal import Decimal
from typing import Any


def _field(record: dict, column: str) -> Any:
    value = record.get(column, "")
    return "" if value is None else value


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_col: str,
    key_val: Any,
    out_col: str,
) -> Any:
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_col, "") == key_val:
            value = row.get(out_col, "")
            return "" if value is None else value

    return ""


def _failure(code: str, message: str) -> dict:
    return {
        "code": code,
        "message": message,
        "severity": "BLOCK",
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Run applicable legacy rules in rule-file order and collect all failures."""
    errors: list[dict] = []

    if table == "ORD_HEADER":
        # ORD-001
        if event in ("INSERT", "UPDATE"):
            discount = _number(_field(record, "DISC_PCT"))
            if not (discount >= Decimal(0) and discount <= Decimal(100)):
                errors.append(
                    _failure("E5001", "Discount out of range")
                )

        # ORD-002
        if event == "UPDATE":
            discount = _number(_field(record, "DISC_PCT"))
            owner_uid = _field(record, "OWNER_UID")
            owner_role = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                owner_uid,
                "ROLE_ID",
            )
            passes = not (
                discount > Decimal(20)
                and owner_role != "MGR"
                and owner_role != "ADMIN"
            )
            if not passes:
                errors.append(
                    _failure(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

        # ORD-003
        if event == "UPDATE":
            old_status = (
                ""
                if old is None
                else _field(old, "STAT_CD")
            )
            new_status = _field(record, "STAT_CD")
            passes = not (
                old_status == "I"
                and new_status != "I"
                and new_status != "X"
            )
            if not passes:
                errors.append(
                    _failure(
                        "E5003",
                        "Invoiced order can only be cancelled",
                    )
                )

    elif table == "ORD_LINE":
        # ORD-004
        if event in ("INSERT", "UPDATE"):
            quantity = _number(_field(record, "QTY"))
            if not quantity > Decimal(0):
                errors.append(
                    _failure("E5004", "Quantity must be positive")
                )

        # ORD-005
        if event == "INSERT":
            product_id = _field(record, "PROD_ID")
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                product_id,
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                errors.append(
                    _failure("E5005", "Product not active")
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
